import{_ as a,o as i,c as l,a2 as n}from"./chunks/framework.BrrkjrmM.js";const u=JSON.parse('{"title":"项目介绍","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1780728201000}'),t={name:"guide/index.md"};function s(o,e,r,p,c,d){return i(),l("div",null,[...e[0]||(e[0]=[n(`<h1 id="项目介绍" tabindex="-1">项目介绍 <a class="header-anchor" href="#项目介绍" aria-label="Permalink to &quot;项目介绍&quot;">​</a></h1><p>Nimble-API 是一个轻量级的 TypeScript API 服务框架，采用 monorepo 架构，包含两个独立发布的包。</p><h2 id="设计理念" tabindex="-1">设计理念 <a class="header-anchor" href="#设计理念" aria-label="Permalink to &quot;设计理念&quot;">​</a></h2><ul><li><strong>最小化依赖</strong> — eventhub 零外部依赖，api-service 仅依赖 eventhub</li><li><strong>渐进增强</strong> — 可以只用 eventhub 做事件管理，也可以搭配 api-service 做完整的 API 客户端</li><li><strong>类型优先</strong> — 所有 API 都经过完整的 TypeScript 类型推导</li><li><strong>可扩展</strong> — 适配器模式支持任意 HTTP 层，钩子系统支持任意生命周期拦截</li></ul><h2 id="包概览" tabindex="-1">包概览 <a class="header-anchor" href="#包概览" aria-label="Permalink to &quot;包概览&quot;">​</a></h2><h3 id="nimble-api-eventhub" tabindex="-1">@nimble-api/eventhub <a class="header-anchor" href="#nimble-api-eventhub" aria-label="Permalink to &quot;@nimble-api/eventhub&quot;">​</a></h3><p>轻量级事件管理器，基于 Map + Set 实现 O(1) 的监听器查找。支持：</p><ul><li>类型安全的事件订阅与派发</li><li><code>once()</code> Promise 语义 + timeout + filter</li><li><code>emitSerial()</code> 顺序异步执行</li><li><code>events()</code> AsyncIterable 流式消费</li><li>AbortSignal 取消订阅</li><li>快照安全的 emit（emit 期间可增删监听器）</li><li>Debounce/Throttle（防抖/节流，支持 options 传参和链式调用）</li></ul><h3 id="nimble-api-api-service" tabindex="-1">@nimble-api/api-service <a class="header-anchor" href="#nimble-api-api-service" aria-label="Permalink to &quot;@nimble-api/api-service&quot;">​</a></h3><p>功能完备的 API 客户端框架，依赖 eventhub 做事件派发。支持：</p><ul><li>完整 HTTP 方法（GET/POST/PUT/PATCH/DELETE）</li><li>LRU 缓存 + TTL + SWR 模式</li><li>可配置重试策略（指数退避/固定延迟）</li><li>钩子管线（请求前、响应后、重试前、错误处理）</li><li>请求去重（相同请求并发只发一次）</li><li>端点级 lock/debounce/throttle（并发锁、防抖、节流）</li><li>Schema 校验（Zod 等任意 parse/safeParse 实现）</li><li>实体标签提取与缓存失效</li><li>可插拔适配器（内置 fetch 和 uni-app）</li></ul><h2 id="架构关系" tabindex="-1">架构关系 <a class="header-anchor" href="#架构关系" aria-label="Permalink to &quot;架构关系&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span>@nimble-api/eventhub  ←  零依赖</span></span>
<span class="line"><span>         ↑</span></span>
<span class="line"><span>         |  依赖（事件派发）</span></span>
<span class="line"><span>         |</span></span>
<span class="line"><span>@nimble-api/api-service  ←  依赖 eventhub</span></span></code></pre></div><p>两个包可以独立使用，也可以组合使用。api-service 通过 <code>EventHubLike</code> 接口接收任意兼容的事件中心实例。</p>`,14)])])}const b=a(t,[["render",s]]);export{u as __pageData,b as default};
